import kotlin.math.sin

/**
 * The animal whose paw lifts the tubes, chosen in the Colors sheet. [size] scales the paw and [arm] is the
 * forearm's thickness, both in tube widths.
 */
enum class PawKind(val label: String, internal val size: Float, internal val arm: Float) {
    CAT("Cat", 1f, 0.6f),
    DOG("Dog", 1.08f, 0.64f),
    BEAR("Bear", 1.2f, 0.74f),
    CHICKEN("Chicken", 1.15f, 0.22f),
    RABBIT("Rabbit", 1f, 0.56f),
    FROG("Frog", 1f, 0.34f),
    RACCOON("Raccoon", 1f, 0.5f),
    PANDA("Panda", 1.12f, 0.7f);

    companion object {
        /** The kind saved as [name], or [CAT] for a name we don't know. */
        fun byName(name: String?): PawKind = entries.firstOrNull { it.name == name } ?: CAT
    }
}

/** The paw in use. */
val LocalPawKind = compositionLocalOf { PawKind.CAT }

/**
 * A paw's colors. Fur follows the palette's accent; skin, pads and claws are fixed tints blended into it, so
 * every paw still sits well in every palette.
 */
internal class PawLook(val fur: Color, val pad: Color, val nail: Color, val line: Color, val arm: Color)

internal fun pawLook(kind: PawKind, palette: Palette): PawLook {
    val base = palette.accent
    fun tint(rgb: Long, f: Float) = lerp(base, Color(rgb), f)
    val fur = when (kind) {
        PawKind.CHICKEN -> tint(0xFFE8B04E, 0.75f)
        PawKind.FROG -> tint(0xFF7DB46A, 0.78f)
        PawKind.RACCOON -> tint(0xFF45434C, 0.75f)
        PawKind.PANDA -> tint(0xFF2E2A30, 0.85f)
        else -> base
    }
    val dark = kind == PawKind.RACCOON || kind == PawKind.PANDA
    val pad = when (kind) {
        PawKind.CAT -> tint(0xFFE48FA6, 0.75f)
        PawKind.DOG -> tint(0xFF4E3E3C, 0.72f)
        PawKind.BEAR -> tint(0xFF5A4038, 0.72f)
        PawKind.RABBIT -> lerp(base, Color.White, 0.3f)
        PawKind.CHICKEN -> lerp(fur, Color(0xFFC0702A), 0.45f)
        PawKind.FROG -> lerp(fur, Color(0xFFE4EFA6), 0.55f)
        PawKind.RACCOON -> lerp(fur, Color.Black, 0.3f)
        PawKind.PANDA -> lerp(fur, Color(0xFFA08C96), 0.4f)
    }
    val nail = when (kind) {
        PawKind.RACCOON, PawKind.PANDA -> lerp(fur, Color.White, 0.45f)
        PawKind.CHICKEN -> lerp(fur, Color(0xFF6B4A2E), 0.55f)
        else -> lerp(base, Color(0xFF4A3C36), 0.6f)
    }
    val line = if (dark) lerp(fur, Color.Black, 0.45f) else lerp(fur, palette.onAccent, 0.35f)
    val arm = when (kind) {
        PawKind.RACCOON -> tint(0xFF9A98A0, 0.55f)
        PawKind.CHICKEN, PawKind.FROG, PawKind.PANDA -> fur
        else -> base
    }
    return PawLook(fur, pad, nail, line, arm)
}

/** Draws [block] at [alpha] as one layer, so the paw's overlapping shapes fade together. */
internal inline fun DrawScope.withAlpha(alpha: Float, block: DrawScope.() -> Unit) {
    if (alpha <= 0f) return
    if (alpha >= 1f) return block()
    val canvas = drawContext.canvas
    // The arm reaches past this canvas to the screen edge, so the layer must not clip to it.
    canvas.saveLayer(Rect(-100_000f, -100_000f, 100_000f, 100_000f), Paint().apply { this.alpha = alpha })
    block()
    canvas.restore()
}

/** The longest the forearm is drawn, in tube widths. */
internal const val MAX_ARM = 4f

/**
 * The forearm behind a paw at [grip], [thick] wide, reaching out towards the screen edge at x = [edge] on [side]
 * (-1 left, 1 right), but at most [MAX_ARM] widths, rising by [rise] degrees on its way out. It fades out to
 * nothing at its far end, so it needs no shoulder.
 */
internal fun DrawScope.drawForearm(kind: PawKind, look: PawLook, grip: Offset, w: Float, thick: Float, side: Int, rise: Float, edge: Float) {
    val r = rise * PI.toFloat() / 180f
    // On a wide screen it stops short of the edge, fading out, so it doesn't stretch across the window like a beam.
    val length = minOf(abs(edge - grip.x) / cos(r) + w, MAX_ARM * w)
    val solid = (w * 1.3f / length).coerceIn(0f, 0.6f)
    val end = grip + Offset(side * length, 0f)
    rotate(-side * rise, pivot = grip) {
        val edgeLine = w * 0.04f
        // The outline fades out sooner than the fur, so the arm's far end is a soft light blur, not a dark band.
        for ((color, grow) in listOf(look.line.copy(alpha = 0.6f) to edgeLine, look.arm to 0f)) {
            val gone = if (grow > 0f) solid + (1 - solid) * 0.45f else 1f
            val brush = Brush.linearGradient(
                0f to color,
                solid to color,
                gone to color.copy(alpha = 0f),
                start = grip,
                end = end,
            )
            drawRoundRect(
                brush,
                topLeft = Offset(minOf(grip.x, end.x), grip.y - thick / 2 - grow),
                size = Size(length, thick + grow * 2),
                cornerRadius = CornerRadius(thick / 2 + grow),
            )
        }
        if (kind == PawKind.CHICKEN) {
            // Scales down the leg.
            var d = w * 0.35f
            while (d < w * 2.2f) {
                val x = grip.x + side * d
                drawLine(look.line.copy(alpha = 0.5f), Offset(x, grip.y - thick * 0.42f), Offset(x + side * thick * 0.25f, grip.y + thick * 0.42f), strokeWidth = w * 0.025f)
                d += w * 0.16f
            }
        }
    }
}

/**
 * One paw of [kind], centred at [c], about [w] wide (times the kind's size), its toes turned [rotation] degrees
 * clockwise from pointing up. Soft rounded shapes with a thin outline, in the toned-down style of the board.
 * A paw holding a tube shows us its back: fur, creases between the toes and the claws, with the pads against
 * the glass. With [pads] it turns its palm to us instead, as the picker's icons do.
 */
internal fun DrawScope.drawPaw(kind: PawKind, look: PawLook, c: Offset, w: Float, rotation: Float, pads: Boolean = false) {
    val s = w * kind.size
    rotate(rotation, pivot = c) { PawPen(this, c, s, look, pads).draw(kind) }
}

/**
 * The box the paw of [kind] covers, outline and claws included, in tube widths around its middle, with the toes
 * pointing to -y as [drawPaw] draws it before turning it. It comes from the same shapes the drawing uses.
 */
internal fun pawBounds(kind: PawKind): Rect = measured.getOrPut(kind) {
    val look = PawLook(Color.Black, Color.Black, Color.Black, Color.Black, Color.Black)
    PawPen(null, Offset.Zero, kind.size, look).apply { draw(kind) }.bounds
}

private val measured = mutableMapOf<PawKind, Rect>()

/**
 * Draws in a paw's own frame: (0, 0) is its middle, units are the paw's width, and the toes point to -y.
 * Without a [scope] it draws nothing and only collects the [bounds] of what it would draw.
 */
private class PawPen(val scope: DrawScope?, val c: Offset, val s: Float, val look: PawLook, val pads: Boolean = false) {
    val edge = 0.04f
    var bounds = Rect.Zero
        private set

    private fun cover(left: Float, top: Float, right: Float, bottom: Float) {
        val box = Rect(at(left, top), at(right, bottom))
        bounds = if (bounds == Rect.Zero) box else Rect(
            minOf(bounds.left, box.left), minOf(bounds.top, box.top), maxOf(bounds.right, box.right), maxOf(bounds.bottom, box.bottom),
        )
    }

    fun draw(kind: PawKind) = when (kind) {
        PawKind.CAT -> cat()
        PawKind.DOG -> dog()
        PawKind.BEAR -> bear()
        PawKind.CHICKEN -> chicken()
        PawKind.RABBIT -> rabbit()
        PawKind.FROG -> frog()
        PawKind.RACCOON -> raccoon()
        PawKind.PANDA -> panda()
    }

    fun at(x: Float, y: Float) = c + Offset(x * s, y * s)

    fun oval(color: Color, x: Float, y: Float, rx: Float, ry: Float) {
        cover(x - rx, y - ry, x + rx, y + ry)
        scope?.drawOval(color, topLeft = at(x - rx, y - ry), size = Size(rx * 2 * s, ry * 2 * s))
    }

    fun circle(color: Color, x: Float, y: Float, r: Float) = oval(color, x, y, r, r)

    fun stroke(color: Color, from: Offset, to: Offset, width: Float) {
        val half = width / 2
        cover(minOf(from.x, to.x) - half, minOf(from.y, to.y) - half, maxOf(from.x, to.x) + half, maxOf(from.y, to.y) + half)
        scope?.drawLine(color, at(from.x, from.y), at(to.x, to.y), strokeWidth = width * s, cap = StrokeCap.Round)
    }

    /** Draws [shape] twice: grown by the outline width in the line color, then in fur on top, as one silhouette. */
    fun silhouette(fill: Color = look.fur, shape: (Color, Float) -> Unit) {
        shape(look.line.copy(alpha = 0.6f), edge)
        shape(fill, 0f)
    }

    /** A point [length] from [from], [degrees] clockwise from straight up. */
    fun toward(from: Offset, degrees: Float, length: Float): Offset {
        val r = degrees * PI.toFloat() / 180f
        return from + Offset(sin(r) * length, -cos(r) * length)
    }

    /** A curved, tapering claw growing out of [base] in direction [degrees], bending away from the middle. */
    fun claw(base: Offset, degrees: Float, length: Float, width: Float) {
        val tip = toward(base, degrees, length)
        val across = if (degrees < 0f) -90f else 90f
        val side = toward(Offset.Zero, degrees + 90f, width / 2)
        val mid = (base + tip) / 2f + toward(Offset.Zero, degrees + across, length * 0.2f)
        // A quadratic curve stays inside its control points, so they bound the claw.
        for (p in listOf(base - side, mid - side * 0.6f, mid + side * 0.6f, tip, base + side)) cover(p.x, p.y, p.x, p.y)
        val canvas = scope ?: return
        val path = Path().apply {
            val start = at(base.x - side.x, base.y - side.y)
            val m1 = at(mid.x - side.x * 0.6f, mid.y - side.y * 0.6f)
            val m2 = at(mid.x + side.x * 0.6f, mid.y + side.y * 0.6f)
            val t = at(tip.x, tip.y)
            val end = at(base.x + side.x, base.y + side.y)
            moveTo(start.x, start.y)
            quadraticTo(m1.x, m1.y, t.x, t.y)
            quadraticTo(m2.x, m2.y, end.x, end.y)
            close()
        }
        canvas.drawPath(path, look.nail)
    }

    /** From behind: a crease between each two neighbouring toes, running back from the gap towards the wrist. */
    fun creases(toes: List<Pair<Float, Float>>, length: Float, wrist: Offset = Offset(0f, 0.2f)) {
        for ((a, b) in toes.zipWithNext()) {
            val gap = Offset((a.first + b.first) / 2, (a.second + b.second) / 2)
            val back = (wrist - gap).let { it / it.getDistance() }
            stroke(look.line.copy(alpha = 0.6f), gap - back * 0.05f, gap + back * length, 0.03f)
        }
    }

    /** From behind: the light catching the rounded back of the paw. */
    fun sheen(x: Float, y: Float, rx: Float, ry: Float) = oval(lerp(look.fur, Color.White, 0.16f), x, y, rx, ry)

    /** The cat: a round paw with four toes and pink beans. */
    fun cat() {
        val toes = listOf(-0.36f to -0.3f, -0.12f to -0.42f, 0.12f to -0.42f, 0.36f to -0.3f)
        silhouette { color, g ->
            oval(color, 0f, 0.02f, 0.5f + g, 0.4f + g)
            for ((x, y) in toes) circle(color, x, y, 0.17f + g)
        }
        if (pads) {
            oval(look.pad, 0f, -0.05f, 0.24f, 0.17f)
            for ((x, y) in toes) oval(look.pad, x, y - 0.025f, 0.075f, 0.085f)
        } else {
            sheen(-0.08f, 0.06f, 0.26f, 0.18f)
            creases(toes, 0.14f)
        }
    }

    /** The dog: a broader paw, oval toes with blunt nails and a big three-lobed pad. */
    fun dog() {
        val toes = listOf(-0.4f to -0.22f, -0.14f to -0.4f, 0.14f to -0.4f, 0.4f to -0.22f)
        for ((x, y) in toes) oval(look.nail, x * 1.1f, y - 0.17f, 0.06f, 0.08f)
        silhouette { color, g ->
            oval(color, 0f, 0.05f, 0.52f + g, 0.42f + g)
            for ((x, y) in toes) oval(color, x, y, 0.16f + g, 0.19f + g)
        }
        if (pads) {
            oval(look.pad, 0f, 0.02f, 0.25f, 0.17f)
            circle(look.pad, -0.13f, 0.12f, 0.12f)
            circle(look.pad, 0.13f, 0.12f, 0.12f)
            for ((x, y) in toes) oval(look.pad, x, y + 0.01f, 0.09f, 0.11f)
        } else {
            sheen(-0.08f, 0.1f, 0.28f, 0.19f)
            creases(toes, 0.16f)
        }
    }

    /** The bear: big and heavy, five toes in an arc with long curved claws. */
    fun bear() {
        val toes = listOf(-0.44f to -0.14f, -0.24f to -0.33f, 0f to -0.4f, 0.24f to -0.33f, 0.44f to -0.14f)
        for ((x, y) in toes) {
            val degrees = x * 85f
            claw(toward(Offset(x, y), degrees, 0.08f), degrees, 0.24f, 0.11f)
        }
        silhouette { color, g ->
            oval(color, 0f, 0.08f, 0.54f + g, 0.44f + g)
            for ((x, y) in toes) circle(color, x, y, 0.14f + g)
        }
        if (pads) {
            oval(look.pad, 0f, 0.06f, 0.3f, 0.16f)
            circle(look.pad, -0.2f, 0.12f, 0.1f)
            circle(look.pad, 0.2f, 0.12f, 0.1f)
            for ((x, y) in toes) circle(look.pad, x, y + 0.01f, 0.08f)
        } else {
            sheen(-0.1f, 0.14f, 0.3f, 0.2f)
            creases(toes, 0.14f)
        }
    }

    /** The chicken: three long thin scaly toes ahead, one short one behind, and small claws. */
    fun chicken() {
        val base = Offset(0f, 0.16f)
        val toes = listOf(-30f to 0.6f, 0f to 0.68f, 30f to 0.6f, 160f to 0.3f)
        for ((degrees, length) in toes) claw(toward(base, degrees, length - 0.03f), degrees, 0.12f, 0.06f)
        silhouette { color, g ->
            for ((degrees, length) in toes) stroke(color, base, toward(base, degrees, length), 0.13f + g * 2)
            circle(color, base.x, base.y, 0.11f + g)
        }
        for ((degrees, length) in toes) {
            var f = 0.3f
            while (f < length - 0.05f) {
                val mid = toward(base, degrees, f)
                stroke(look.pad.copy(alpha = 0.8f), toward(mid, degrees - 90f, 0.035f), toward(mid, degrees + 90f, 0.035f), 0.02f)
                f += 0.1f
            }
        }
        if (pads) circle(look.pad.copy(alpha = 0.5f), base.x, base.y, 0.05f)
    }

    /** The rabbit: a long, fluffy foot with soft toes and no pads. */
    fun rabbit() {
        val toes = listOf(-0.22f to -0.38f, -0.075f to -0.48f, 0.075f to -0.48f, 0.22f to -0.38f)
        val tufts = listOf(-0.34f to 0.02f, 0.34f to 0.02f, -0.3f to 0.24f, 0.3f to 0.24f, -0.33f to -0.18f, 0.33f to -0.18f)
        silhouette { color, g ->
            oval(color, 0f, 0.02f, 0.34f + g, 0.5f + g)
            for ((x, y) in toes) circle(color, x, y, 0.12f + g)
            for ((x, y) in tufts) circle(color, x, y, 0.08f + g)
        }
        if (pads) oval(look.pad, 0f, 0.06f, 0.2f, 0.3f) else sheen(-0.06f, 0.08f, 0.16f, 0.26f)
        for (x in listOf(-0.15f, 0f, 0.15f)) {
            stroke(look.line.copy(alpha = 0.45f), Offset(x, -0.5f + abs(x) * 0.5f), Offset(x, -0.36f + abs(x) * 0.5f), 0.025f)
        }
    }

    /** The frog: four long fingers with round sticky tips, webbed in between. */
    fun frog() {
        val base = Offset(0f, 0.14f)
        val fingers = listOf(-50f to 0.5f, -17f to 0.58f, 17f to 0.58f, 50f to 0.5f)
        // The web lies between the fingers, so it adds nothing to the bounds.
        if (scope != null) {
            val web = Path().apply {
                moveTo(at(base.x, base.y).x, at(base.x, base.y).y)
                fingers.forEachIndexed { i, (degrees, length) ->
                    val p = toward(base, degrees, length * 0.68f)
                    if (i == 0) {
                        lineTo(at(p.x, p.y).x, at(p.x, p.y).y)
                    } else {
                        // Each web edge sags in towards the palm.
                        val (before, beforeLength) = fingers[i - 1]
                        val sag = toward(base, (before + degrees) / 2, (beforeLength + length) / 2 * 0.45f)
                        quadraticTo(at(sag.x, sag.y).x, at(sag.x, sag.y).y, at(p.x, p.y).x, at(p.x, p.y).y)
                    }
                }
                close()
            }
            scope.drawPath(web, look.fur.copy(alpha = 0.7f))
        }
        silhouette { color, g ->
            circle(color, base.x, base.y, 0.24f + g)
            for ((degrees, length) in fingers) {
                stroke(color, base, toward(base, degrees, length), 0.1f + g * 2)
                val tip = toward(base, degrees, length)
                circle(color, tip.x, tip.y, 0.1f + g)
            }
        }
        // The sticky discs face the glass; from behind they are just a paler rim.
        val disc = if (pads) look.pad else lerp(look.fur, look.pad, 0.35f)
        for ((degrees, length) in fingers) {
            val tip = toward(base, degrees, length)
            circle(disc, tip.x, tip.y, 0.06f)
        }
        val spots = if (pads) {
            listOf(Offset(-0.07f, 0.2f), Offset(0.08f, 0.1f))
        } else {
            listOf(Offset(-0.07f, 0.2f), Offset(0.08f, 0.1f), Offset(-0.02f, 0.02f), Offset(0.1f, 0.26f))
        }
        for (spot in spots) circle(look.line.copy(alpha = 0.3f), spot.x, spot.y, 0.035f)
    }

    /** The raccoon: a small dark hand with five slender fingers and pale little claws. */
    fun raccoon() {
        val fingers = listOf(
            Triple(Offset(-0.2f, 0.16f), -64f, 0.34f),
            Triple(Offset(-0.15f, 0.0f), -24f, 0.48f),
            Triple(Offset(-0.05f, -0.04f), -7f, 0.54f),
            Triple(Offset(0.06f, -0.03f), 10f, 0.5f),
            Triple(Offset(0.16f, 0.02f), 28f, 0.42f),
        )
        for ((base, degrees, length) in fingers) claw(toward(base, degrees, length + 0.02f), degrees, 0.08f, 0.05f)
        silhouette { color, g ->
            oval(color, 0f, 0.14f, 0.3f + g, 0.28f + g)
            for ((base, degrees, length) in fingers) stroke(color, base, toward(base, degrees, length), 0.13f + g * 2)
        }
        if (pads) {
            oval(look.pad, 0.02f, 0.16f, 0.18f, 0.15f)
            for ((base, degrees, length) in fingers) {
                val tip = toward(base, degrees, length - 0.02f)
                circle(look.pad, tip.x, tip.y, 0.045f)
            }
        } else {
            // Knuckle creases across each finger.
            sheen(-0.05f, 0.16f, 0.16f, 0.12f)
            for ((base, degrees, length) in fingers) {
                for (f in listOf(0.45f, 0.75f)) {
                    val k = toward(base, degrees, length * f)
                    stroke(look.line.copy(alpha = 0.6f), toward(k, degrees - 90f, 0.04f), toward(k, degrees + 90f, 0.04f), 0.025f)
                }
            }
        }
    }

    /** The panda: a round black paw with five plump toes and greyish pads. */
    fun panda() {
        val toes = listOf(-0.42f to -0.14f, -0.22f to -0.32f, 0f to -0.38f, 0.22f to -0.32f, 0.42f to -0.14f)
        silhouette { color, g ->
            oval(color, 0f, 0.06f, 0.52f + g, 0.44f + g)
            for ((x, y) in toes) circle(color, x, y, 0.15f + g)
        }
        if (pads) {
            oval(look.pad, 0f, 0.09f, 0.3f, 0.19f)
            oval(look.pad, 0.36f, 0.26f, 0.07f, 0.09f)
            for ((x, y) in toes) circle(look.pad, x, y + 0.01f, 0.08f)
        } else {
            sheen(-0.1f, 0.12f, 0.28f, 0.19f)
            creases(toes, 0.14f)
        }
        for ((x, y) in toes) claw(toward(Offset(x, y), x * 80f, 0.13f), x * 80f, 0.05f, 0.04f)
    }
}
