package io.colorsand.core

/** A pour of [amount] units from tube index [from] to tube index [to]. */
data class Move(val from: Int, val to: Int, val amount: Int)

/**
 * The arrangement of all tubes at one point in a game. Immutable.
 *
 * Pouring rules (the classic sort puzzle rules):
 * - You pour from a non-empty tube into a different tube that is not full.
 * - The target must be empty or have the same color on top as the source.
 * - The whole top run of that color moves, as much as fits in the target.
 */
data class Board(val tubes: List<Tube>) {

    val isSolved: Boolean get() = tubes.all { it.isSorted }

    /** How many units a pour from [from] to [to] would move, or 0 if the pour is not allowed. */
    fun pourAmount(from: Int, to: Int): Int {
        if (from == to || from !in tubes.indices || to !in tubes.indices) return 0
        val source = tubes[from]
        val target = tubes[to]
        val color = source.topColor ?: return 0
        if (!target.accepts(color)) return 0
        return minOf(source.topRunLength, target.freeSpace)
    }

    fun canPour(from: Int, to: Int): Boolean = pourAmount(from, to) > 0

    /** Returns the board after pouring from [from] to [to] with the move made, or null if the pour is illegal. */
    fun pour(from: Int, to: Int): Pair<Board, Move>? {
        val amount = pourAmount(from, to)
        if (amount == 0) return null
        val color = tubes[from].topColor!!
        val next = tubes.toMutableList()
        next[from] = tubes[from].removeTop(amount)
        next[to] = tubes[to].add(color, amount)
        return Board(next) to Move(from, to, amount)
    }

    /** All legal pours from this board. */
    fun legalMoves(): List<Move> = buildList {
        for (from in tubes.indices) for (to in tubes.indices) {
            val amount = pourAmount(from, to)
            if (amount > 0) add(Move(from, to, amount))
        }
    }

    /** Count of each color across all tubes. */
    fun colorCounts(): Map<SandColor, Int> = tubes.flatMap { it.layers }.groupingBy { it }.eachCount()

    override fun toString(): String = tubes.joinToString(" ")

    companion object {
        /** Builds a board of tubes with [capacity] from text, one string per tube, bottom to top. */
        fun parse(capacity: Int, vararg tubes: String): Board = Board(tubes.map { Tube.parse(capacity, it) })
    }
}
