package io.colorsand.ui.arena

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.drawscope.DrawScope
import io.colorsand.core.Arena

/**
 * Texture over one layer of sand in a tube, so it reads as sand rather than paint: the layer spans the full
 * width of the drawing area, from [top] down [height]. [seed] keeps a layer's grains still from frame to frame.
 *
 * Each [arena] will get its own grain; for now they share the speckles the game always had.
 */
internal fun DrawScope.drawSandTexture(arena: Arena, top: Float, height: Float, seed: Int) {
    var state = seed * 1103515245 + 12345
    fun next(): Float {
        state = state * 1103515245 + 12345
        return ((state ushr 8) and 0xFFFF) / 65535f
    }
    val grain = size.width * 0.03f
    repeat(70) {
        val shade = if (next() > 0.5f) Color.White.copy(alpha = 0.2f) else Color.Black.copy(alpha = 0.18f)
        val side = grain * (0.5f + next())
        drawRect(shade, topLeft = Offset(next() * size.width, top + next() * (height - side)), size = Size(side, side))
    }
}
