package io.colorsand.ui

/** Where the player's progress is kept. Each platform supplies its own (SharedPreferences, localStorage, ...). */
interface ProgressStore {
    /** The level to open on start: the first level not yet solved. */
    var level: Int

    /** The name of the chosen [Palette]; see [Palettes.byName]. */
    var palette: String

    /** The player's [CustomScheme] in its [CustomScheme.encode] form, used when [palette] is "Custom". */
    var customColors: String

    /** The name of the chosen [PawKind]; see [PawKind.byName]. */
    var paw: String
        get() = PawKind.CAT.name
        set(_) {}

    /** The best stars earned per level, in [StarBook.encode] form ("1:3,2:2"). */
    var stars: String
        get() = ""
        set(_) {}
}

/** Keeps progress only while the app runs. Used in tests and as a fallback. */
class InMemoryProgressStore(
    override var level: Int = 1,
    override var palette: String = Palettes.Classic.name,
    override var customColors: String = CustomScheme.Default.encode(),
    override var paw: String = PawKind.CAT.name,
    override var stars: String = "",
) : ProgressStore
