package io.colorsand.ui

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.saveable.Saver
import androidx.compose.runtime.setValue
import io.colorsand.core.Board
import io.colorsand.core.GameSession
import io.colorsand.core.Hint
import io.colorsand.core.Arena
import io.colorsand.core.Levels
import io.colorsand.core.Move
import io.colorsand.core.SandColor
import io.colorsand.core.Stars

/**
 * A pour the player just made, for the pour animation: [amount] units of [color] went [move.from] -> [move.to],
 * starting from [before]. [id] grows with every pour, so the same move made twice is still two events.
 */
data class PourEvent(val id: Int, val move: Move, val color: SandColor, val before: Board)

/** A short message shown above the controls. */
enum class Notice { DEAD_END, NO_HINT }

/**
 * Screen state for one game: wraps [GameSession] and exposes everything the UI draws as Compose state.
 *
 * Tap a tube to pick it up, tap another to pour into it. Solving a level saves the next one to [store].
 * [startLevel] and [replay] restore a game in progress (see [saver]).
 * Any level up to [unlockedLevel] can be opened with [goToLevel]; replaying a solved one never lowers progress.
 */
class GameController(
    private val store: ProgressStore,
    startLevel: Int = store.level,
    replay: List<Pair<Int, Int>> = emptyList(),
) {
    var levelNumber by mutableStateOf(startLevel.coerceAtLeast(1))
        private set

    private var session = GameSession(Levels[levelNumber]).apply {
        replay.forEach { (from, to) -> pour(from, to) }
    }

    var board: Board by mutableStateOf(session.board)
        private set
    var moveCount by mutableStateOf(0)
        private set
    var canUndo by mutableStateOf(false)
        private set
    var isStuck by mutableStateOf(false)
        private set

    /** The tube that is picked up, waiting for a target. */
    var selected: Int? by mutableStateOf(null)
        private set

    /** The pour suggested by the last hint, until the board changes. */
    var hint: Move? by mutableStateOf(null)
        private set
    var notice: Notice? by mutableStateOf(null)
        private set

    /** The highest level the player may open: the first one not yet solved. */
    var unlockedLevel by mutableStateOf(store.level.coerceAtLeast(1))
        private set

    /** The pour made by the last tap. Undo, restart and a new level clear it, since those aren't animated. */
    var lastPour: PourEvent? by mutableStateOf(null)
        private set
    private var pourCount = 0

    val isSolved: Boolean get() = board.isSolved

    /** The arena the current level is played in. */
    val arena: Arena get() = Arena.of(levelNumber)

    /** The best stars earned on every level so far. */
    var stars: StarBook by mutableStateOf(StarBook.decode(store.stars))
        private set

    /** Stars earned by the play-through that just solved the level, or 0 while it is unsolved. */
    var earnedStars by mutableStateOf(0)
        private set

    init {
        sync()
    }

    fun tap(tube: Int) {
        if (isSolved || tube !in board.tubes.indices) return
        val from = selected
        when {
            from == null -> if (!board.tubes[tube].isEmpty) selected = tube
            from == tube -> selected = null
            else -> pour(from, tube)
        }
    }

    private fun pour(from: Int, to: Int) {
        val before = board
        val move = session.pour(from, to)
        when {
            move != null -> {
                sync()
                lastPour = PourEvent(++pourCount, move, before.tubes[from].topColor!!, before)
            }
            // Not a legal pour: pick up the tapped tube instead, if it has sand.
            !board.tubes[to].isEmpty -> selected = to
            else -> selected = null
        }
    }

    fun undo() {
        if (session.undo()) sync()
    }

    fun restart() {
        session.restart()
        sync()
    }

    fun showHint() {
        if (isSolved) return
        when (val result = session.hint()) {
            is Hint.Pour -> {
                hint = result.move
                selected = null
                notice = null
            }
            Hint.DeadEnd -> notice = Notice.DEAD_END
            Hint.Unknown -> notice = Notice.NO_HINT
            Hint.Solved -> Unit
        }
    }

    fun nextLevel() {
        if (!isSolved) return
        levelNumber += 1
        session = GameSession(Levels[levelNumber])
        sync()
    }

    /** Opens level [number] fresh, if it is unlocked. Returns whether it did. */
    fun goToLevel(number: Int): Boolean {
        if (number !in 1..unlockedLevel) return false
        levelNumber = number
        session = GameSession(Levels[number])
        sync()
        return true
    }

    private fun sync() {
        board = session.board
        moveCount = session.moveCount
        canUndo = session.canUndo
        isStuck = session.isStuck
        selected = null
        hint = null
        notice = null
        lastPour = null
        earnedStars = 0
        if (session.isSolved) {
            // Unlock first: it matters most if saving the stars fails.
            if (store.level <= levelNumber) store.level = levelNumber + 1
            earnedStars = Stars.earned(session.moveCount, Stars.par(levelNumber))
            stars = stars.record(levelNumber, earnedStars)
            store.stars = stars.encode()
        }
        unlockedLevel = store.level.coerceAtLeast(1)
    }

    companion object {
        /**
         * Saves the level and the pours made so far, so a game survives Android activity recreation
         * (rotation, process death). Restoring replays the pours, which also restores undo.
         */
        fun saver(store: ProgressStore): Saver<GameController, List<Int>> = Saver(
            // An ArrayList of Ints is what an Android Bundle can hold.
            save = { game -> ArrayList(listOf(game.levelNumber) + game.session.moves.flatMap { listOf(it.from, it.to) }) },
            restore = { saved ->
                GameController(store, saved.first(), saved.drop(1).chunked(2).map { (from, to) -> from to to })
            },
        )
    }
}
