package io.colorsand.ui.arena

import androidx.compose.foundation.Canvas
import androidx.compose.runtime.Composable
import androidx.compose.runtime.staticCompositionLocalOf
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import io.colorsand.core.Arena
import io.colorsand.ui.Palette

/** The arena being played. Read it wherever the look depends on the place: the scenery, the sand, the stands. */
val LocalArena = staticCompositionLocalOf { Arena.PLAYGROUND }

/**
 * The scenery behind the board for [arena]. The [palette] still sets the overall tint, so every color scheme
 * keeps its mood; the arena adds the place.
 *
 * For now a plain sky in the palette's colors over a strip of ground in the arena's sand color.
 */
@Composable
fun ArenaBackground(arena: Arena, palette: Palette, modifier: Modifier = Modifier) {
    Canvas(modifier) {
        drawRect(Brush.verticalGradient(listOf(palette.backgroundTop, palette.backgroundBottom)))
        val ground = groundColor(arena).copy(alpha = 0.35f)
        val top = size.height * 0.86f
        val hill = Path().apply {
            moveTo(0f, top)
            quadraticBezierTo(size.width * 0.5f, top - size.height * 0.05f, size.width, top)
            lineTo(size.width, size.height)
            lineTo(0f, size.height)
            close()
        }
        drawPath(hill, ground)
        drawRect(Color.Black.copy(alpha = 0.06f), Offset(0f, size.height * 0.97f), Size(size.width, size.height * 0.03f))
    }
}

/** The color of the arena's own sand: the ground it is set on. */
fun groundColor(arena: Arena): Color = when (arena) {
    Arena.PLAYGROUND -> Color(0xFFD9B77E)
    Arena.BEACH -> Color(0xFFF1DDB0)
    Arena.DESERT -> Color(0xFFE59A4F)
}
